/// Result of an OAuth token exchange/refresh, surfaced to Dart for persistence.
class OAuthResult {
  final String accessToken;
  final String refreshToken;

  /// Absolute Unix expiry time (seconds), computed from expires_in.
  final PlatformInt64 expiresAt;
  final PlatformInt64 userId;

  const OAuthResult({
    required this.accessToken,
    required this.refreshToken,
    required this.expiresAt,
    required this.userId,
  });

  @override
  int get hashCode =>
      accessToken.hashCode ^
      refreshToken.hashCode ^
      expiresAt.hashCode ^
      userId.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is OAuthResult &&
          runtimeType == other.runtimeType &&
          accessToken == other.accessToken &&
          refreshToken == other.refreshToken &&
          expiresAt == other.expiresAt &&
          userId == other.userId;
}

/// The identity a personal access token was proven to carry. Carries no token.
class PersonalTokenProfile {
  final PlatformInt64 userId;
  final String username;

  const PersonalTokenProfile({required this.userId, required this.username});

  @override
  int get hashCode => userId.hashCode ^ username.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is PersonalTokenProfile &&
          runtimeType == other.runtimeType &&
          userId == other.userId &&
          username == other.username;
}
